using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

public class ConfigResource : Resource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "McpHttpServer",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false,
        }
    };

    public override ResourceMetadata Metadata => new()
    {
        Uri = "config://app/settings",
        Name = "Application Settings",
        Description = "Returns the current application configuration",
        MimeType = "application/json",
    };

    public override Task<ReadResourceResult> ReadAsync(
        RequestContext<ReadResourceRequestParams> request,
        CancellationToken cancellationToken)
    {
        var json = JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions
        {
            WriteIndented = true
        });

        return Task.FromResult(new ReadResourceResult(new ResourceContents[]
        {
            new TextResourceContents
            {
                Uri = Metadata.Uri,
                MimeType = "application/json",
                Text = json,
            }
        }));
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Echoes the input message back with a timestamp.")]
    public static string Echo(string message)
    {
        return $"[{DateTime.UtcNow:O}] Echo: {message}";
    }

    [McpServerTool, Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;
}

